"OLAYLAR_ORTACAG_ORTADOGU:0910-01-15:0":{"b": ["Ebû Abdullah entrou em Raqqada com Ubeydullah el-Mehdî; a imamação fatímida começou de facto", "cf944741"], "d": ["Ebû Abdullah tomou Raqqada, capital dos Aglábidas, e expulsou o último emir, Ziyâdetullah (296/909); a 29 Rebîülâhir 297 (15 de janeiro de 910) entrou em Raqqada com Ubeydullah.", "99f93307"]},
"OLAYLAR_ORTACAG_ORTADOGU:0915-07-17:0":{"b": ["Ubeydullah el-Mehdî fundou a cidade de Mahdia", "f6aef126"], "d": ["Mehdî fundou a cidade chamada Mahdia numa península da costa da Ifríquia oriental (303/915).", "eccb119a"]},
"OLAYLAR_ORTACAG_ORTADOGU:0920-05-23:0":{"b": ["Mahdia foi proclamada capital fatímida", "a160b592"], "d": ["Cinco anos depois da sua fundação, Mahdia foi proclamada capital (308/920).", "eb88ec52"]},
"OLAYLAR_ORTACAG_ORTADOGU:0929-02-14:0":{"b": ["Os carmatas ocuparam Meca e levaram a Pedra Negra a al-Ahsa (Lahsa); o Estado carmata do Bahrein, dono de Lahsa no primeiro testemunho datado", "5ca42bf9"], "d": ["Os carmatas ismailitas (Estado carmata do Bahrein) ocuparam Meca em 317 H / 929 e levaram a Pedra Negra a al-Ahsa (Lahsa); contudo, ela foi devolvida ao seu lugar vinte anos depois. No atlas, Lahsa, que pertencia ao Califado abássida, está registrada em nome dos carmatas a partir deste primeiro testemunho datado.", "a6a3faa1"]},
